insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('6eb24deb-6013-53a9-9965-c4848f6329e5', '280773c9-dd5f-5cb9-bcbc-c744228bb8a1', 'The number of muskrat in a 115-acre area is estimated to be 2,070. What is the estimated population density, in muskrat per acre, of this area?', '["18", "2,088", "115", "133"]'::jsonb, 1, null),
  ('aa061723-cafd-50eb-b18d-709d058a75c2', '280773c9-dd5f-5cb9-bcbc-c744228bb8a1', 'Note: Figure not drawn to scale.
The triangle shown has one side with a length of $x$ inches and two sides each with a length of $y$ inches. The perimeter of the triangle is 63 inches. Which equation represents this situation?', '["$2x + y = 63$", "$x + 2y = 63$", "$2x + 2y = 63$", "$x + y = 63$"]'::jsonb, 2, '![figure](/q/sep25/002.webp)'),
  ('3fabe6db-d8c3-58d6-addb-93e18fe50c14', '280773c9-dd5f-5cb9-bcbc-c744228bb8a1', 'A jar has 170 buttons, and 20% of these buttons are green. How many buttons in the jar are green?', '[]'::jsonb, 3, null),
  ('13776933-d6f0-568b-8731-f02ad6beb447', '280773c9-dd5f-5cb9-bcbc-c744228bb8a1', 'There are a total of 3,500 milligrams of phosphorus in a sample of soil. Each kilogram of this sample contains 700 milligrams of phosphorus. Which equation represents this situation, where is the mass, in kilograms, of the sample of soil?', '["$3,500x = 700$", "$x + 3,500 = 700$", "$x + 700 = 3,500$", "$700x = 3,500$"]'::jsonb, 4, null),
  ('12204cae-bacb-5f35-8354-db0d5be73099', '280773c9-dd5f-5cb9-bcbc-c744228bb8a1', 'The function $f$ is defined by $f(x) = \frac{1}{2}(x + 11)$. What is the value of $f(3)$?', '["22", "28", "7", "14"]'::jsonb, 5, null),
  ('311b5e2d-05cc-50e0-9d19-4cd50fc0c966', '280773c9-dd5f-5cb9-bcbc-c744228bb8a1', 'If $7x + 5 = 22$, what is the value of $2(7x + 5)$?', '["34", "66", "44", "54"]'::jsonb, 6, null),
  ('914d84c2-d6f9-569c-966b-da9a9426524b', '280773c9-dd5f-5cb9-bcbc-c744228bb8a1', 'Triangles $ABC$ and $DEF$ are congruent, where $A$ corresponds to $D$, and $B$ and $E$ are right angles. The measure of angle $A$ is $63°$. What is the measure, in degrees, of angle $F$?', '[]'::jsonb, 7, null),
  ('2db78088-71c9-54ce-a8ad-6186f70dcbb0', '280773c9-dd5f-5cb9-bcbc-c744228bb8a1', 'A savings account is opened with an initial deposit of $9000$. The amount of money in the account t years after the initial deposit is given by the function $f(t) = 9000(1.02)^{2t}$. Which of the following is the best interpretation of the statement “$f(9)$ is approximately equal to $12854.22$” in this context?', '["Every 9 years, the amount of money, in dollars, in the account increases by 12,854.22.", "9 years after the initial deposit, the amount of money, in dollars, in the account is 12,854.22.", "9 years after the initial deposit, the amount of money, in dollars, in the account has increased by 12,854.22.", "Every 9 years, the amount of money, in dollars, in the account decreases by 12,854.22."]'::jsonb, 8, null),
  ('bb55c9b0-a3fd-5210-803c-bf9659774fcb', '280773c9-dd5f-5cb9-bcbc-c744228bb8a1', '$y = (x - 7)(x + 3)$ Which table gives four values of $x$ and the corresponding values of $y$ for the given quadratic equation?', '["| $x$ | -1 | 0 | 1 | 2 |\n| $y$ | 11 | 3 | -3 | -7 |", "| $x$ | -1 | 0 | 1 | 2 |\n| $y$ | -28 | -21 | -14 | -7 |", "| $x$ | -1 | 0 | 1 | 2 |\n| $y$ | -16 | -21 | -24 | -25 |", "| $x$ | -1 | 0 | 1 | 2 |\n| $y$ | 3 | 10 | 17 | 24 |"]'::jsonb, 9, null),
  ('9217c4e5-8325-56a2-982d-428805a7a0c3', '280773c9-dd5f-5cb9-bcbc-c744228bb8a1', 'In the linear function $f$, $f(0) = 9$ and $f(7) = 9$. Which equation defines $f$?', '["$f(x) = 9$", "$f(x) = x + 9$", "$f(x) = 7$", "$f(x) = 0$"]'::jsonb, 10, null),
  ('3900f9f9-7939-5efa-a497-8f336f05943c', '280773c9-dd5f-5cb9-bcbc-c744228bb8a1', 'A length of 550 meters is equal to how many $\text{decimetres}$? (1 meter = 10 decimeters)', '[]'::jsonb, 11, null),
  ('1ba397a2-85d5-5d8a-9ea5-21ca5262a168', '280773c9-dd5f-5cb9-bcbc-c744228bb8a1', 'An arborist studying forestland in Illinois estimates that there are at least 40 and no more than 70 hickory trees per acre in a certain forest. Which of the following best represents the arborist’s estimate of the number of hickory trees, $x$, that are in a 7-acre section of this forest?', '["$490 \\le x \\le 980$", "$280 \\le x \\le 490$", "$47 \\le x \\le 77$", "$40 \\le x \\le 70$"]'::jsonb, 12, null),
  ('cda1accd-fd6c-5280-8132-f83e36e2176a', '280773c9-dd5f-5cb9-bcbc-c744228bb8a1', 'For the polynomial function $p$, the graph of $y = p(x)$ in the $xy$-plane crosses through the points $(-6,0)$, $(0,12)$, $(7,0)$, and $(14,0)$. What is the value of $p(0)$?', '[]'::jsonb, 13, null),
  ('c61d47e3-a964-5177-9153-c65462e133a7', '280773c9-dd5f-5cb9-bcbc-c744228bb8a1', 'The graph of $-11x + 2.2y = -605$ in the $xy$-plane has intercepts at $(a,0)$ and $(0,b)$. What is the value of $ab$?', '[]'::jsonb, 14, null),
  ('7eff9d63-840d-58bd-b225-41fe6f1613c6', '280773c9-dd5f-5cb9-bcbc-c744228bb8a1', '$x + 21y = 38$
$4x + 3y = 17$
The solution to the given system of equations is $(x,y)$. What is the value of $y$?', '[]'::jsonb, 15, null),
  ('b277a059-b4bc-5c33-aa68-c55aebecf8fa', '280773c9-dd5f-5cb9-bcbc-c744228bb8a1', 'Which of the following is closest to the slope of a line of best fit for the data shown?', '["$-8.05$", "$-0.17$", "$-6.05$", "$-2.17$"]'::jsonb, 16, 'As part of a study on sedimentary habitats, the water temperature was recorded at different depths below the surface of the water in the northern Alboran Sea. The data shown in the scatterplot give the recorded temperature, in degrees Celsius, for 7 depths, in meters, below the surface of the water.

![figure](/q/sep25/003.webp)'),
  ('5d6881eb-0000-545e-87a6-052195126f06', '280773c9-dd5f-5cb9-bcbc-c744228bb8a1', '$a = \frac{4}{9}b + 8$
The given equation relates the positive numbers $a$ and $b$. Which equation correctly expresses $b$ in terms of $a$?', '["$b = \\frac{9}{4}a - 18$", "$b = \\frac{4}{9}a - 18$", "$b = \\frac{9}{4}a - 8$", "$b = \\frac{4}{9}a + 8$"]'::jsonb, 17, null),
  ('e56391d7-00c8-5703-b201-171a80fff3d3', '280773c9-dd5f-5cb9-bcbc-c744228bb8a1', 'The measure of an angle, in radians, is $(99)(2)π$. What is the measure of the angle, in $\text{degrees}$?', '["$(99)(2)(360)$", "$(\\frac{99}{2})(360)$", "$(180)(99)(360)$", "$(99)(360)$"]'::jsonb, 18, null),
  ('bdb08b5e-4a89-526e-86ae-f203ce882f70', '280773c9-dd5f-5cb9-bcbc-c744228bb8a1', '$x^{2} + (\sqrt{k - 3})x + 26 = 0$
In the given equation, $k$ is a constant. The equation has exactly one real solution. What is the value of $k$?', '["29", "104", "107", "101"]'::jsonb, 19, null),
  ('d556b2f0-8806-5f54-b94a-e5590e5ac270', '280773c9-dd5f-5cb9-bcbc-c744228bb8a1', 'In triangles $RST$ and $XY Z$ shown, $\overline{XY}$ is parallel to $\overline{TS}$ and $\tan R = \frac{180}{299}$. What is the value of $\sin X$ in triangle $XY Z$?', '["$\\frac{299}{349}$", "$\\frac{180}{349}$", "$\\frac{180}{479}$", "$\\frac{299}{180}$"]'::jsonb, 20, '![figure](/q/sep25/004.webp)'),
  ('103f614d-407c-5611-82da-fc50e6d77a2f', '280773c9-dd5f-5cb9-bcbc-c744228bb8a1', '$∣x + 4∣ + 4 = ∣2x - 11∣ + 4$ What is the smallest solution to the given equation?', '[]'::jsonb, 21, null),
  ('d178a584-1354-5267-9b5d-1ef6285a46c0', '280773c9-dd5f-5cb9-bcbc-c744228bb8a1', '$y = 3x^{2} - 12x + 18$
$y + 2 = 0$
How many solutions are there to the given system of equations?', '["There are exactly 2 solutions.", "There are exactly 3 solutions.", "There are no solutions.", "There is exactly 4 solution."]'::jsonb, 22, null)
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('6eb24deb-6013-53a9-9965-c4848f6329e5', 0, null, '**Choice A is correct.** Population density is the number of muskrat divided by the number of acres. Compute $2070 \div 115$. Since $115 \times 18 = 115 \times (20 - 2) = 2300 - 230 = 2070$, the density is $18$ muskrat per acre.
**Choice B is incorrect.** $2088$ is near the total population, not a per-acre density; it results from an arithmetic error and is far too large for per-acre value.
**Choice C is incorrect.** $115$ is the number of acres, not the result of dividing muskrat by acres, so it does not represent muskrat per acre.
**Choice D is incorrect.** $133$ is not equal to $2070 \div 115$ and arises from an incorrect division.
**Faster approach:** For density, immediately divide total by area; recognize common factor $115 \times 18 = 2070$ to avoid long division.'),
  ('aa061723-cafd-50eb-b18d-709d058a75c2', 1, null, '**Choice B is correct.** The perimeter of a triangle is the sum of its three side lengths. The triangle has one side of length $x$ and two sides each of length $y$, so the perimeter is $x + y + y$, which simplifies to $x + 2y$. Setting this equal to 63 gives $x + 2y = 63$, which matches choice B.
**Choice A is incorrect.** $2x + y = 63$ would be correct only if there were two sides of length $x$ and one side of length $y$, but the figure shows one $x$ and two $y$ sides.
**Choice C is incorrect.** $2x + 2y = 63$ doubles every side and gives a sum of four terms, not the three sides shown.
**Choice D is incorrect.** $x + y = 63$ omits one of the two $y$ sides; it accounts for only two sides instead of all three.
**Faster approach:** Write perimeter = sum of sides: one $x$ plus two $y$’s → $x + 2y$, then set equal to 63. That directly yields $x + 2y = 63$ for every problem with one of one variable and two of another.'),
  ('3fabe6db-d8c3-58d6-addb-93e18fe50c14', null, array['34']::text[], '**The correct answer is 34.** To find 20% of 170, convert the percent to a decimal and multiply: $20% = 0.20$, so $0.20 \times 170 = 34$. Therefore there are 34 green buttons.
**Faster approach:** Recognize that 10% of 170 is 17, so 20% is twice that: $2 \times 17 = 34$. This quick mental-step method works for any problem asking for simple percent multiples of a given total.'),
  ('13776933-d6f0-568b-8731-f02ad6beb447', 3, null, '**Choice D is correct.** If $x$ is the mass in kilograms and each kilogram contains 700 mg of phosphorus, then the total phosphorus is $700 \cdot x$. That total equals 3,500 mg, so the correct equation is $700x = 3,500$. Solving gives $x = 5$, meaning the sample has 5 kg.
**Choice A is incorrect.** $3,500x = 700$ says the total (3,500) times $x$ equals 700, which reverses the roles of total and rate.
**Choice B is incorrect.** $x + 3,500 = 700$ treats the quantities as additive rather than a rate times amount; units and values do not match.
**Choice C is incorrect.** $x + 700 = 3,500$ also treats the relationship as addition instead of multiplication by the per-kilogram rate.
**Faster approach:** Use the rate equation rate × amount = total. Here, $700 \times x = 3,500$, so divide total by rate to get $x = 3,500/700 = 5$. This approach applies to all rate problems.'),
  ('12204cae-bacb-5f35-8354-db0d5be73099', 2, null, '**Choice C is correct.** The definition gives $f(x) = \frac{1}{2}(x + 11)$. Substituting $x = 3$ yields $f(3) = \frac{1}{2}(3 + 11) =$ $\frac{1}{2}(14) = 7$, so choice C is correct.
**Choice A is incorrect.** 22 would result from multiplying 11 by 2, which does not follow from the given function evaluation.
**Choice B is incorrect.** 28 is twice 14 and is not produced by the given formula after substitution.
**Choice D is incorrect.** 14 is the value of $(3 + 11)$ before multiplying by $\frac{1}{2}$, not the final value of $f(3)$. **Faster approach:** Perform the substitution and do the simple mental arithmetic: add 3 and 11 to get 14, then take half to get 7.'),
  ('311b5e2d-05cc-50e0-9d19-4cd50fc0c966', 2, null, '**Choice C is correct.** The equation gives $7x + 5 = 22$. The expression asked for is $2(7x + 5)$, so multiply both sides of the given equation by 2 to get $2(7x + 5) = 2 \cdot 22 = 44$, which matches choice C.
**Choice A is incorrect.** 34 would be $22 + 12$ or $2 \cdot 17$, which has no direct relation to $2(7x + 5)$ here.
**Choice B is incorrect.** 66 is $3 \cdot 22$; the problem asks for twice, not three times, the quantity $7x + 5$.
**Choice D is incorrect.** 54 is neither $2 \cdot 22$ nor any straightforward multiple of the given value $22$, so it does not equal $2(7x + 5)$.
**Faster approach:** Use direct substitution/multiplication: since $7x + 5 = 22$, compute $2(7x + 5) = 2 \times 22$ immediately without solving for $x$.'),
  ('914d84c2-d6f9-569c-966b-da9a9426524b', null, array['27']::text[], '**The correct answer is 27.** Triangles ABC and DEF are congruent with corresponding vertices A↔D, B↔E, and C↔F, so corresponding angles are equal. Given angle B = 90° and angle A = 63° in triangle ABC, the third angle C equals $180° - 90° - 63° = 27°$. Because C corresponds to F, angle F also measures $27°$.
**Faster approach:** Use angle-sum in a triangle immediately: third angle = $180°-$ (given two angles). Then transfer that measure to the corresponding angle in the congruent triangle. This avoids extra steps or constructions.'),
  ('2db78088-71c9-54ce-a8ad-6186f70dcbb0', 1, null, '**Choice B is correct.** The function $f(t) = 9000(1.02)^{2t}$ represents the amount of money in the savings account after $t$ years. When we evaluate $f(9)$, we are determining the amount of money in the account 9 years after the initial deposit. Therefore, $f(9) \approx 12854.22$ means that 9 years after the initial deposit, the total amount of money in the account is approximately \$12,854.22.
Now, let’s examine why the other options are incorrect:
**Option A:** This option states that every 9 years, the amount in the account increases by \$12,854.22. This interpretation is incorrect because $f(9)$ gives the total amount after 9 years, not the increase. **Option C:** This option suggests that the amount has increased by \$12,854.22 after 9 years. While the account has increased in value, \$12,854.22 is the total amount after 9 years, not the increase alone, making this interpretation incorrect.
**Option D:** This option wrongly claims that the amount decreases by \$12,854.22 every 9 years. Since the amount is increasing due to interest, this statement is entirely false.'),
  ('bb55c9b0-a3fd-5210-803c-bf9659774fcb', 2, null, '**Choice C is correct.** Use the given form $y = (x - 7)(x + 3)$. For $x = -1$: $y = (-1 - 7)(-1 + 3) = (-8)(2) =$ $-16$. For $x = 0$: $y = (0 - 7)(0 + 3) = (-7)(3) = -21$. For $x = 1$: $y = (1 - 7)(1 + 3) = (-6)(4) = -24$. For $x = 2$: $y = (2 - 7)(2 + 3) = (-5)(5) = -25$. These values match the table in choice C.
**Choice A is incorrect.** Its $y$ values (11, 3, -3, -7) do not match the computed values (−16, −21, −24, −25).
**Choice B is incorrect.** Its $y$ values decrease by 7 each step (−28, −21, −14, −7), which does not fit the quadratic values computed from the formula.
**Choice D is incorrect.** Its $y$ values (3, 10, 17, 24) are increasing linearly and do not match the quadratic outputs found above.
**Faster approach:** Plug each given $x$ directly into the factored form $y = (x - 7)(x + 3)$ (or expand to $x^{2} -$ $4x - 21$) and compute; direct substitution quickly eliminates wrong tables.'),
  ('9217c4e5-8325-56a2-982d-428805a7a0c3', 0, null, '**Choice A is correct.** The function takes the same value at two different inputs: $f(0) = 9$ and $f(7) = 9$. For a linear function, equal outputs at two distinct inputs mean the slope is $0$, so the function is the constant $f(x) = 9$, which matches choice A.
**Choice B is incorrect.** $f(x) = x + 9$ gives $f(0) = 9$ but $f(7) = 16$, not $9$, so it does not satisfy $f(7) = 9$.
**Choice C is incorrect.** $f(x) = 7$ would give $f(0) = 7$, contradicting the given $f(0) = 9$.
**Choice D is incorrect.** $f(x) = 0$ gives $f(0) = 0$, which contradicts $f(0) = 9$.
**Faster approach:** Notice two outputs are equal at different inputs, so slope $= (9 - 9)/(7 - 0) = 0$; therefore the function is the constant $f(x) = 9$.'),
  ('3900f9f9-7939-5efa-a497-8f336f05943c', null, array['5500']::text[], '**The correct answer is 5500.** To convert meters to decimetres, use the given equivalence $1 \text{meter} =$ $10 \text{decimetres}$. Multiply the number of meters by 10 to find the number of decimetres: $550 \times 10 = 5500$. Thus 550 meters equals 5500 decimetres.
**Faster approach:** Recognize that converting to a smaller metric unit multiplies by the unit factor. Multiply 550 by 10 immediately to get 5500 decimetres. This direct multiplication works for any conversion where the factor is known (e.g., meters to centimeters, kilometers to meters).'),
  ('1ba397a2-85d5-5d8a-9ea5-21ca5262a168', 1, null, '**Choice B is correct.** The arborist estimates between 40 and 70 hickory trees per acre. For 7 acres, multiply both endpoints by 7 to get the range: $7 \cdot 40 = 280$ and $7 \cdot 70 = 490$, so $280 \le x \le 490$.
**Choice A is incorrect.** Multiplying the per-acre bounds by 7 gives $280$ and $490$, not $490$ and $980$; Choice A is the result of multiplying by 12.25 or otherwise incorrect scaling.
**Choice C is incorrect.** The numbers $47$ and $77$ are not the products of $40$ and $70$ with 7; they are far too small to represent 7 acres.
**Choice D is incorrect.** $40 \le x \le 70$ describes the number of trees per single acre, not for a 7-acre section.
**Faster approach:** Multiply the lower and upper per-acre bounds by the number of acres (7) to get the range for the total count.'),
  ('cda1accd-fd6c-5280-8132-f83e36e2176a', null, array['12']::text[], '**The correct answer is 12.** The problem gives that the graph of $y = p(x)$ passes through the point $(0,12)$. By definition of a function value at an input, $p(0)$ is the $y$-coordinate of the point on the graph where $x = 0$. Since that point is $(0,12)$, $p(0) = 12$.
**Faster approach:** Read the given points carefully — the ordered pair $(0,12)$ immediately yields $p(0) = 12$ without any further computation. This direct reading of coordinates applies to every question asking for $f(a)$ when the point $(a,b)$ is listed.'),
  ('c61d47e3-a964-5177-9153-c65462e133a7', null, array['-15125']::text[], '**The correct answer is -15125.** To find the intercepts, set one variable to 0 each time. For the x-intercept, set $y = 0$: $-11x = -605$, so $x = \frac{-605}{-11} = 55$, so $a = 55$. For the y-intercept, set $x = 0$: $2.2y = -605$, so $y =$ $\frac{-605}{2.2} = -275$, so $b = -275$. Multiplying gives $ab = 55 \cdot (-275) = -15125$.
**Faster approach:** Use intercept formulas directly: x-intercept is $-\frac{C}{A}$ and y-intercept is $-\frac{C}{B}$ for $Ax + By = C$ . Then $ab = (-\frac{C}{A})(-\frac{C}{B}) = \frac{C^{2}}{AB}$; here straightforward substitution or the two quick substitutions shown above are fastest.'),
  ('7eff9d63-840d-58bd-b225-41fe6f1613c6', null, array['5/3']::text[], '**The correct answer is 5/3.** Substitute $x = 38 - 21y$ (from $x + 21y = 38$) into $4x + 3y = 17$: $4(38 - 21y) +$ $3y = 17$. Simplify to get $152 - 84y + 3y = 17$, so $152 - 81y = 17$. Then $-81y = -135$, and $y = 135/81 = 5/3$.
**Faster approach:** Use elimination by multiplying the first equation by 4 to get $4x + 84y = 152$ and subtract the second equation $4x + 3y = 17$ to obtain $81y = 135$, so $y = 135/81 = 5/3$. This same elimination step works for any similar two-equation system with matching $x$ coefficients.'),
  ('b277a059-b4bc-5c33-aa68-c55aebecf8fa', 1, null, '**Choice B is correct.** The slope of the line of best fit is the change in temperature divided by the change in depth. Reading two points on the drawn trend line (for example, approximately $(10,22)$ and $(70,13)$) gives slope $m = \frac{13-22}{70-10} = \frac{-9}{60} = -0.15$, which is closest to $-0.17$.
**Choice A is incorrect.** $-8.05$ is far too large in magnitude; that would mean a drop of about 8°C per meter, which contradicts the plotted scale and points.
**Choice C is incorrect.** $-6.05$ is likewise much too steep; the data show a gradual decline across 60 meters, not a 6°C per meter change.
**Choice D is incorrect.** $-2.17$ is still much steeper than the observed trend; the actual decline is about $-0.15$ °C per meter.
**Faster approach:** Pick two clearly spaced points on the drawn trend line (one near the left and one near the right), compute $Δy/Δx$, and compare to the answer choices — this straightforward slope calculation works for every such scatterplot question.'),
  ('5d6881eb-0000-545e-87a6-052195126f06', 0, null, '**Choice A is correct.** Starting with $a = \frac{4}{9}b + 8$, subtract 8 from both sides to get $a - 8 = \frac{4}{9}b$. Then multiply both sides by the reciprocal $\frac{9}{4}$ to isolate $b$: $b = \frac{9}{4}(a - 8) = \frac{9}{4}a - \frac{9}{4} \cdot 8 = \frac{9}{4}a - 18$.
**Choice B is incorrect.** It has the wrong coefficient for $b$ in terms of $a$; multiplying by $\frac{4}{9}$ instead of $\frac{9}{4}$ does not invert the original coefficient.
**Choice C is incorrect.** Although it uses the correct multiplier $\frac{9}{4}$ on $a$, it subtracts 8 instead of $18$, so the constant term is wrong.
**Choice D is incorrect.** It leaves the same orientation as the original equation (scaling $a$ by $\frac{4}{9}$ and adding 8) instead of isolating $b$, so it does not solve for $b$ in terms of $a$.
**Faster approach:** Undo operations in reverse order: subtract 8, then multiply by the reciprocal $\frac{9}{4}$ to get $b =$ $\frac{9}{4}(a - 8)$, which simplifies to choice A.'),
  ('e56391d7-00c8-5703-b201-171a80fff3d3', 3, null, '**Choice D is correct.** To convert radians to degrees, multiply by $180/π$. The angle is $(99)(2)π$ radians, so in degrees it equals $(99)(2)π \cdot \frac{180}{π}$. The $π$ cancels, giving $(99)(2)(180) = 99(360)$, which matches Choice D. **Choice A is incorrect.** Choice A is $(99)(2)(360)$, which is double the correct value because it treats the $180$ conversion factor as $360$ after doubling; the correct multiplication is $(99)(2)(180)$ which simplifies to $99(360)$, not $(99)(2)(360)$.
**Choice B is incorrect.** Choice B simplifies to $99 \cdot 180$, which is half the correct value; it comes from incorrectly dividing by 2 instead of multiplying by it.
**Choice C is incorrect.** Choice C is $(180)(99)(360)$, an extra factor of $360$ that is not present in the radian-to-degree conversion; it is far larger than the correct result.
**Faster approach:** Cancel the $π$ immediately and apply the conversion $\times \frac{180}{π}$. Here $(99)(2)π \times \frac{180}{π} = 99 \times 360$, so pick D.'),
  ('bdb08b5e-4a89-526e-86ae-f203ce882f70', 2, null, '**Choice C is correct.** For a quadratic $ax^{2} + bx + c = 0$ to have exactly one real solution, its discriminant must be zero: $b^{2} - 4ac = 0$. Here $a = 1$, $b =\sqrt{k - 3}$, and $c = 26$, so $(\sqrt{k - 3})^{2} - 4(1)(26) = 0$. That gives $k - 3 -$ $104 = 0$, so $k = 107$. The value is admissible because $k - 3 \ge 0$ is satisfied.
**Choice A is incorrect.** If $k = 29$, then $b^{2} = k - 3 = 26$, and the discriminant would be $26 - 104 = -78 < 0$, so no real solutions.
**Choice B is incorrect.** If $k = 104$, then $b^{2} = 101$, and the discriminant $101 - 104 = -3 < 0$, so no real solutions.
**Choice D is incorrect.** If $k = 101$, then $b^{2} = 98$, and the discriminant $98 - 104 = -6 < 0$, so no real solutions.
**Faster approach:** Immediately set the discriminant $b^{2} - 4ac = 0$ (here $k - 3 - 104 = 0$) to solve for $k$ — this works for any quadratic required to have exactly one real root.'),
  ('d556b2f0-8806-5f54-b94a-e5590e5ac270', 0, null, '**Choice A is correct.** Because $\overline{XY} ∥ \overline{TS}$, triangle $XY Z$ is similar to triangle $RST$. From $\tan R = \frac{180}{299}$ we can take $TS = 180k$ and $RT = 299k$ for some $k$, so $RS =\sqrt{180^{2} + 299^{2}} = 349k$. Angle $X$ corresponds to angle $S$, so $\sin X = \sin S = \frac{RT}{RS} = \frac{299k}{349k} = \frac{299}{349}$.
**Choice B is incorrect.** $\frac{180}{349}$ equals $\sin R$ (opposite $TS$ over hypotenuse $RS$), not $\sin X$.
**Choice C is incorrect.** $\frac{180}{479}$ uses a wrong hypotenuse; the correct hypotenuse for legs $180$ and $299$ is $349$, not $479$.
**Choice D is incorrect.** $\frac{299}{180} > 1$, which is impossible for the sine of an acute angle.
**Faster approach:** When given $\tan θ = \frac{a}{b}$, draw a right triangle with opposite $a$ and adjacent $b$, compute hypotenuse $\sqrt{a^{2} + b^{2}}$, then use similarity or complementary-angle relations to get the requested sine or cosine.'),
  ('103f614d-407c-5611-82da-fc50e6d77a2f', null, array['7/3']::text[], '**The correct answer is 7/3.** Start by subtracting 4 from both sides to get $∣x + 4∣ = ∣2x - 11∣$. Absolute values are equal when their insides are equal or negatives of each other. Set up the two linear equations: $x + 4 =$ $2x - 11$ and $x + 4 = -(2x - 11)$. Solving the first gives $x = 15$. Solving the second gives $x + 4 = -2x + 11$, so $3x = 7$ and $x = 7/3$. The smaller solution is $7/3$.
**Faster approach:** Use the property $∣A∣ = ∣B∣ ⟺ A = B \text{or} A = -B$ and immediately form the two linear equations; solve both and choose the smaller root. This avoids case-by-case sign analysis of the absolute values.'),
  ('d178a584-1354-5267-9b5d-1ef6285a46c0', 2, null, '**Choice C is correct.** Substitute $y = -2$ into $y = 3x^{2} - 12x + 18$ to get $3x^{2} - 12x + 18 = -2$, or $3x^{2} - 12x +$ $20 = 0$. The discriminant of this quadratic is $b^{2} - 4ac = (-12)^{2} - 4(3)(20) = 144 - 240 = -96$, which is negative, so there are no real $x$ solutions and thus no solutions to the system.
**Choice A is incorrect.** A positive discriminant would be needed for two real solutions; here the discriminant is negative.
**Choice B is incorrect.** A system of a quadratic and a horizontal line cannot have exactly three intersection points.
**Choice D is incorrect.** Four intersection points are impossible for a single quadratic and a horizontal line.
**Faster approach:** After substituting $y = -2$, compute the quadratic discriminant $b^{2} - 4ac$. If it is positive, there are 2 intersections; zero gives 1; negative gives 0.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

