values ('da24769f-6b71-5359-b61f-d9827b6e5da6', 'PeaklyTest Sep 2025 · Math · Module 2', 'Math', 'Math, Module 2 of the Sep 2025 PeaklyTest · 22 questions · 35 minutes', 35, 193, true, 'PeaklyTest Sep 2025 · Math', 2)
on conflict (id) do update set title = excluded.title, section = excluded.section, description = excluded.description,
  duration_min = excluded.duration_min, position = excluded.position, form_title = excluded.form_title, module_no = excluded.module_no;
insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('47fdeacb-d0c9-551d-927a-00c1a97731bf', 'da24769f-6b71-5359-b61f-d9827b6e5da6', 'In triangle $EFG$, the sum of the measures of angles $E$ and $F$ is $22°$. What is the measure of angle $G$?', '["$158°$", "$136°$", "$68°$", "$22°$"]'::jsonb, 1, null),
  ('f55137b5-cb87-5273-9b8f-a5658f337e81', 'da24769f-6b71-5359-b61f-d9827b6e5da6', 'Which of the following lists represents a data set with the smallest standard deviation?', '["83, 84, 85, 86, 87", "84, 85, 85, 85, 86", "83, 83, 85, 87, 87", "82, 83, 85, 87, 88"]'::jsonb, 2, null),
  ('eaaf03b7-77ed-508a-a479-1d2a51212098', 'da24769f-6b71-5359-b61f-d9827b6e5da6', '$y = (x - 25)(x - 75)$
$y = 0$
The graphs of the equations in the given system of equations intersect at the point $(x,y)$ in the $xy$- plane. What is a possible value of $x$?', '["75", "100", "3", "0"]'::jsonb, 3, null),
  ('ed426a0c-6228-5803-b349-c5de0590ef04', 'da24769f-6b71-5359-b61f-d9827b6e5da6', 'Which function $f$ gives the rental cost, in dollars, for $x$ hours rental, where $x \ge 1$?', '["$f(x) = 30x + 5$", "$f(x) = 35x$", "$f(x) = 30x + 65$", "$f(x) = 30x$"]'::jsonb, 4, 'The cost to rent a kayak consists of a fixed fee for the first hour and an hourly fee for each additional hour. The table shows the rental cost for 2 hours and for 4 hours.

| Rental hours | Rental cost (dollars) |
| 2 | 65 |
| 4 | 125 |'),
  ('1bb04e7c-cba0-5c3e-a1f1-e9e39cef60fa', 'da24769f-6b71-5359-b61f-d9827b6e5da6', '$g(x) = (38 - 2x)(32 + 2x)$
The function $g$ is defined by the given equation. For what value of $x$ does $g(x)$ reach its maximum?', '["3", "35", "1.5", "17.5"]'::jsonb, 5, null),
  ('6ded6448-b871-54cd-bf20-460c99717aab', 'da24769f-6b71-5359-b61f-d9827b6e5da6', 'Rectangle X has a length of 24 millimeters $(mm)$ and a width of 7.5 $mm$. Right triangle Y has a base of 60 $mm$. The area of rectangle X is 3 times the area of right triangle Y. What is the height, in $mm$, of right triangle Y?', '["6", "2", "3", "1"]'::jsonb, 6, null),
  ('97577beb-18ff-5d18-97dc-6a2707dcac3c', 'da24769f-6b71-5359-b61f-d9827b6e5da6', '', '["21", "2", "$\\frac{21}{4}$", "$\\frac{1}{2}$"]'::jsonb, 7, 'There is a linear relationship between $x$ and $y$. The table shows three values of $x$ and their corresponding values of $y$ in terms of a constant $n$. What is the slope of the line in the $xy$-plane that represents this relationship?

| x | y |
| 0 | n |
| 4 | n + 21 |
| 8 | n + 42 |'),
  ('faffd6f1-cdf8-5805-921d-b14ce7ac9e45', 'da24769f-6b71-5359-b61f-d9827b6e5da6', 'If $a = 5k + 6r$ and $b = 8k - 11r + 3$, which expression is equivalent to $a - b$?', '["$-3k + 17r + 3$", "$-3k - 5r - 3$", "$-3k + 17r - 3$", "$-3k - 5r + 3$"]'::jsonb, 8, null),
  ('cd88817b-90a8-5438-987e-bc0bd9d5ffe5', 'da24769f-6b71-5359-b61f-d9827b6e5da6', 'An exponential function $f$ is defined by $f(x) = c^{x}$, where $c$ is a constant greater than 1. If $f(6) = 25 \cdot$ $f(4)$, what is the value of $c$?', '[]'::jsonb, 9, null),
  ('cdcfe790-6b53-5a57-9f16-dcd64395c03c', 'da24769f-6b71-5359-b61f-d9827b6e5da6', 'The function $g$ is defined by $g(x) = 18x + 31$. For what value of $x$ does $g(x) = 34$?', '[]'::jsonb, 10, null),
  ('c066b572-b386-5770-8b5b-0b94d1895e4b', 'da24769f-6b71-5359-b61f-d9827b6e5da6', 'The equation $h = \frac{9(v-273.15)}{5} + 32$ gives the corresponding temperature $h$, in degrees Fahrenheit, of any substance that has a temperature of $v$ kelvins, where $v > 0$. If a substance has a temperature of 845.33 degrees Fahrenheit, what is the corresponding temperature, in kelvins, of this substance?', '[]'::jsonb, 11, null),
  ('695f102f-4444-50b7-9239-d2d527cb4955', 'da24769f-6b71-5359-b61f-d9827b6e5da6', '$25x^{2} + 10\sqrt{39}x + p = 0$
In the given equation, $p$ is a constant. The equation has exactly one real solution. What is the value of $p$?', '["$\\sqrt{39}$", "$2\\sqrt{39}$", "$\\frac{39}{2}$", "$39$"]'::jsonb, 12, null),
  ('bdc0b4a4-e67f-5b65-9693-278aa043914b', 'da24769f-6b71-5359-b61f-d9827b6e5da6', 'The function $f$ gives the value, in dollars, of a certain piece of equipment after $x$ months of use. If the value of the equipment decreases each $\text{year}$ by $p%$ of its value the preceding year, what is the value of $p$?
$f(x) = 2,570(0.28)^{\frac{x}{12}}$', '["10", "28", "72", "2"]'::jsonb, 13, null),
  ('e5ad5aee-6e25-5feb-9a62-f578303471df', 'da24769f-6b71-5359-b61f-d9827b6e5da6', 'In triangle $RST$, $RS = ST$ and the length of $\overline{RT}$ is 48 units. If $\tan R = \frac{7}{24}$, what is the area, in square units, of triangle $RST$?', '["168", "288", "84", "336"]'::jsonb, 14, null),
  ('df81b425-c53d-578a-b535-c3543d8b5a19', 'da24769f-6b71-5359-b61f-d9827b6e5da6', 'An equilateral triangle has a height of $21\sqrt{3}$ units. What is the length, in units, of one side of this triangle?', '["42", "21$\\sqrt{3}$", "42$\\sqrt{3}$", "21"]'::jsonb, 15, null),
  ('3e56f72a-c4f5-5ec0-9c84-345649c46fc9', 'da24769f-6b71-5359-b61f-d9827b6e5da6', 'Which expression is $\text{NOT}$ a factor of $1,440x^{4} - 56,250$?', '["$90$", "$4x^{2} + 25$", "$2x^{2} - 5$", "$2x + 5$"]'::jsonb, 16, null),
  ('2fd48cb5-eeb5-5070-8ea5-1fab5837d1a0', 'da24769f-6b71-5359-b61f-d9827b6e5da6', '$2970x = 5940x$
How many solutions does the given equation have?', '["Infinitely many", "Exactly two", "Zero", "Exactly one"]'::jsonb, 17, null),
  ('d39373e0-60e8-58c0-92c1-d716d141e4db', 'da24769f-6b71-5359-b61f-d9827b6e5da6', 'In the $xy$-plane, line $r$ passes through the points $(3,12)$ and $(7,13)$. Line $s$ passes through the point $(1,2)$ and is perpendicular to line $r$. An equation of line $s$ is $ax + 7y = c$, where $a$ and $c$ are constants. What is the value of $c$?', '[]'::jsonb, 18, null),
  ('4fdfad5f-c4e3-56a7-abec-0d362bd005e6', 'da24769f-6b71-5359-b61f-d9827b6e5da6', 'One of these neurons will be selected at random. What is the probability of selecting a neuron with a cell body diameter that is less than or equal to 30 micrometers, given that it is not classified as a motor neuron? (Express your answer as a decimal or fraction, not as a percent.)', '[]'::jsonb, 19, 'For 100 neurons, the table summarizes the distribution of classification and cell body diameter.

|  | Cell body diameter (micrometers) |  |  |
| **Classification** | Less than 20 | 20 to 30 | Greater than 30 |
| Sensory neuron | 12 | 7 | 4 |
| Motor neuron | 0 | 17 | 18 |
| Interneuron | 10 | 32 | 0 |'),
  ('9c7c8ed5-8b4b-5f3b-94f8-a59353180d15', 'da24769f-6b71-5359-b61f-d9827b6e5da6', 'The value of a painting increased by 179% from the end of 2017 to the end of 2018 and then decreased by 27% from the end of 2018 to the end of 2019. What was the net percentage increase in the value of the painting from the end of 2017 to the end of 2019?', '["254.33%", "152.00%", "130.67%", "103.67%"]'::jsonb, 20, null),
  ('20145e8c-b5f5-56e1-bf20-eed6b095559d', 'da24769f-6b71-5359-b61f-d9827b6e5da6', '$5x + 3y = 6$
The given equation is one equation in a system of two linear equations. If the system of equations has at least one solution, which of the following equations could be the other equation in the system?
I $7.5x + 4.5y = 9$
II $7.5x - 4.5y = 4.5$', '["II only", "Neither I nor II", "I and II", "I only"]'::jsonb, 21, null),
  ('29adc9d4-dbb8-58ad-8606-7ac4e82afd65', 'da24769f-6b71-5359-b61f-d9827b6e5da6', 'In the figure shown, points $A$, $B$, $C$, and $E$ lie on the circle, and $AB < BC$. Segment $AC$ is perpendicular to segment $BE$ at point $D$, and $BD =\sqrt{390}$. The diameter of the circle is $197$. If $\frac{CD}{AD} = r$ , what is the value of $r$?', '[]'::jsonb, 22, '![figure](/q/sep25/005.webp)')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('47fdeacb-d0c9-551d-927a-00c1a97731bf', 0, null, '**Choice A is correct.** In any triangle the measures of the three interior angles sum to $180°$. If angles $E$ and $F$ together measure $22°$, then angle $G$ measures $180° - 22° = 158°$.
**Choice B is incorrect.** $136°$ would correspond to $E + F = 44°$, not the given $22°$; it does not satisfy the triangle-angle sum.
**Choice C is incorrect.** $68°$ would make $E + F = 112°$, contrary to the stated $22°$.
**Choice D is incorrect.** $22°$ would imply the three angles sum to $44°$, which violates the triangle-angle-sum property.
**Faster approach:** Immediately use the triangle-angle-sum rule $E + F + G = 180°$ and compute $G = 180° -$ $(E + F)$; substitute $E + F = 22°$ to get $158°$.'),
  ('f55137b5-cb87-5273-9b8f-a5658f337e81', 1, null, '**Choice B is correct.** All five lists have mean 85, so compare squared deviations about 85. For B: deviations are -1,0,0,0,1 so squared deviations sum to $1 + 0 + 0 + 0 + 1 = 2$, variance $= 2/5 = 0.4$, and standard deviation $=\sqrt{0.4} \approx 0.632$, the smallest of the four.
**Choice A is incorrect.** A has deviations -2,-1,0,1,2 so squared deviations sum $= 10$, variance $= 10/5 = 2$, SD $=\sqrt{2} \approx 1.414$, larger than B.
**Choice C is incorrect.** C has deviations -2,-2,0,2,2 so squared sum $= 16$, variance $= 16/5 = 3.2$, SD $\approx 1.789$, larger than B.
**Choice D is incorrect.** D has deviations -3,-2,0,2,3 so squared sum $= 26$, variance $= 26/5 = 5.2$, SD $\approx 2.280$, largest of the four.
**Faster approach:** Because all means equal, compare how tightly values cluster around the mean — count repeats and small deviations; the list with most values equal to the mean (or closest to it) has the smallest standard deviation.'),
  ('eaaf03b7-77ed-508a-a479-1d2a51212098', 0, null, '**Choice A is correct.** Because both equations equal $y$, set $(x - 25)(x - 75) = 0$. By the zero-product property, $x - 25 = 0$ or $x - 75 = 0$, so $x = 25$ or $x = 75$. The value $x = 75$ is one of the solutions, so 75 is a possible $x$-coordinate of an intersection point.
**Choice B is incorrect.** If $x = 100$, then $(100 - 25)(100 - 75) = 75 \cdot 25 \ne 0$, so $y \ne 0$ and $(100,0)$ is not an intersection.
**Choice C is incorrect.** If $x = 3$, then $(3 - 25)(3 - 75) = (-22)(-72) \ne 0$, so $y \ne 0$ and $(3,0)$ is not an intersection.
**Choice D is incorrect.** If $x = 0$, then $(0 - 25)(0 - 75) = (-25)(-75) \ne 0$, so $y \ne 0$ and $(0,0)$ is not an intersection.
**Faster approach:** Set the two expressions for $y$ equal and use the zero-product property: solve $(x - 25)(x -$ $75) = 0$ to get the intersection $x$-values immediately.'),
  ('ed426a0c-6228-5803-b349-c5de0590ef04', 0, null, '**Choice A is correct.** Let the fixed first-hour fee be $F$ and the hourly fee for each additional hour be $r$. For 2 hours, $F + r = 65$. For 4 hours, $F + 3r = 125$. Subtracting gives $2r = 60$, so $r = 30$. Then $F = 65 - 30 = 35$. For $x \ge 1$, $f(x) = F + r(x - 1) = 35 + 30(x - 1) = 30x + 5$, which is Choice A.
**Choice B is incorrect.** $f(x) = 35x$ has no fixed first-hour fee separate from the hourly rate; it gives $f(2) = 70$ , not $65$.
**Choice C is incorrect.** $f(x) = 30x + 65$ gives $f(2) = 125$, not $65$, so it does not match the table.
**Choice D is incorrect.** $f(x) = 30x$ gives $f(2) = 60$ and $f(4) = 120$, which do not match the given costs.
**Faster approach:** Compute the hourly rate as the change in cost over change in hours, $r = (125 - 65)/(4 -$ $2) = 30$, then find the fixed first-hour fee by subtracting one hourly increment: $F = 65 - 30 = 35$, yielding $f(x) = 30x + 5$.'),
  ('1bb04e7c-cba0-5c3e-a1f1-e9e39cef60fa', 2, null, '**Choice C is correct.** Expand to get $g(x) = -4x^{2} + 12x + 1216$, a downward-opening parabola. Its vertex (maximum) occurs at $x = -\frac{b}{2a} = -\frac{12}{2(-4)} = 1.5$, so $g(x)$ is maximal at $x = 1.5$.
**Choice A is incorrect.** $x = 3$ is not the vertex; plugging in or using the vertex formula shows the maximum is at $1.5$, not $3$.
**Choice B is incorrect.** $x = 35$ is far from the vertex; the quadratic opens downward so large $∣x∣$ give much smaller values than at $1.5$.
**Choice D is incorrect.** $x = 17.5$ is also not the vertex and yields a much smaller value than at $1.5$.
**Faster approach:** Note the two factors sum to $70$, so their product is maximized when the factors are equal: $38 - 2x = 32 + 2x ⇒ x = 1.5$. This avoids expansion and the vertex formula.'),
  ('6ded6448-b871-54cd-bf20-460c99717aab', 1, null, '**Choice B is correct.** The area of rectangle X is $24 \times 7.5 = 180 \text{mm}^{2}$. That area equals 3 times the area of triangle Y, so the triangle’s area is $180/3 = 60 \text{mm}^{2}$. For a right triangle with base $60$, the area is $\frac{1}{2} \cdot 60 \cdot h =$ $30h$. Set $30h = 60$ and solve to get $h = 2 \text{mm}$.
**Choice A is incorrect.** If $h = 6$, the triangle’s area would be $\frac{1}{2} \cdot 60 \cdot 6 = 180$, which would make rectangle X nine times the triangle’s area, not three times.
**Choice C is incorrect.** If $h = 3$, the triangle’s area would be $\frac{1}{2} \cdot 60 \cdot 3 = 90$, and $180$ would be only twice that area, not three times.
**Choice D is incorrect.** If $h = 1$, the triangle’s area would be $30$, and $180$ would be six times that area, not three times.
**Faster approach:** Compute rectangle area, divide by 3 to get the triangle’s area, then use $\text{area} = \frac{1}{2} \cdot \text{base} \cdot h$ and solve for $h$ (one division).'),
  ('97577beb-18ff-5d18-97dc-6a2707dcac3c', 2, null, '**Choice C is correct.** The slope $m$ of a line is the change in $y$ divided by the change in $x$. Using the points $(0,n)$ and $(4,n + 21)$, $m = \frac{(n + 21) - n}{4 - 0} = \frac{21}{4}$. The other pair $(4,n + 21)$ and $(8,n + 42)$ gives $m =$ $\frac{(n + 42) - (n + 21)}{8 - 4} = \frac{21}{4}$, confirming the same slope.
**Choice A is incorrect.** 21 is the change in $y$ but not the ratio of change in $y$ to change in $x$; you must divide by the change in $x$ (4).
**Choice B is incorrect.** 2 is not the result of $\frac{21}{4}$ and does not match the differences shown in the table. **Choice D is incorrect.** $\frac{1}{2}$ is far smaller than the actual rate of change $\frac{21}{4}$ and is not supported by the table. **Faster approach:** Compute slope directly by taking the difference in the $y$-values over the difference in the corresponding $x$-values for any two rows: $Δy/Δx = (n + 21 - n)/(4 - 0) = 21/4$.'),
  ('faffd6f1-cdf8-5805-921d-b14ce7ac9e45', 2, null, '**Choice C is correct.** Subtracting $b$ from $a$ gives $a - b = (5k + 6r) - (8k - 11r + 3)$. Distribute the subtraction across the parentheses to get $5k + 6r - 8k + 11r - 3$, then combine like terms: $(5 - 8)k + (6 +$ $11)r - 3 = -3k + 17r - 3$, which matches Choice C.
**Choice A is incorrect.** It has the correct $k$ and $r$ coefficients except for the constant term: Choice A is $-3k +$ $17r + 3$, but the correct constant is $-3$, not $+3$.
**Choice B is incorrect.** Its $k$ coefficient $-3$ is correct, but the $r$ coefficient $-5$ is wrong: the $r$ terms $6r -$ $(-11r)$ combine to $17r$, not $-5r$, and the constant sign is also wrong.
**Choice D is incorrect.** It gives $-3k - 5r + 3$, which has both the wrong $r$ coefficient and the wrong constant; the correct result is $-3k + 17r - 3$.
**Faster approach:** Immediately distribute the minus sign across $b$ to get $-8k + 11r - 3$, then combine like terms with $a$ — this one-step distribution plus combining like terms works for all such subtraction problems.'),
  ('cd88817b-90a8-5438-987e-bc0bd9d5ffe5', null, array['5']::text[], '**The correct answer is 5.** Substitute $f(x) = c^{x}$ into the given relation: $f(6) = c^{6}$ and $f(4) = c^{4}$, so $c^{6} = 25 \cdot c^{4}$. Divide both sides by $c^{4}$ (permissible because $c > 1$ implies $c \ne 0$) to get $c^{2} = 25$. Taking the positive square root (since $c > 1$) gives $c = 5$.
**Faster approach:** Use laws of exponents immediately: $c^{6}/c^{4} = c^{6-4} = c^{2} = 25$, then take the positive square root to get $c = 5$. This shortcut (cancelling common exponential factors) works for any similar problem comparing $c^{m}$ and $c^{n}$.'),
  ('cdcfe790-6b53-5a57-9f16-dcd64395c03c', null, array['1/6']::text[], '**The correct answer is 1/6.** To find $x$ when $g(x) = 34$, set $18x + 31 = 34$ and solve. Subtract 31 from both sides to get $18x = 3$. Divide both sides by 18 to obtain $x = 3/18$, which simplifies to $x = 1/6$.
**Faster approach:** Immediately isolate $x$ by computing $34 - 31 = 3$ and then dividing by 18: $x = 3/18 = 1/6$. This direct subtraction-then-division sequence works for any linear function of the form $ax + b = c$.'),
  ('c066b572-b386-5770-8b5b-0b94d1895e4b', null, array['725']::text[], '**The correct answer is 725.** Start with the given formula $h = \frac{9(v-273.15)}{5} + 32$ and solve for $v$. Subtract 32: $h -$ $32 = \frac{9(v-273.15)}{5}$. Multiply both sides by 5: $5(h - 32) = 9(v - 273.15)$. Divide by 9 and add $273.15$: $v = 273.15 +$ $\frac{5(h-32)}{9}$. Substitute $h = 845.33$: $v = 273.15 + \frac{5(845.33-32)}{9} = 273.15 + \frac{5(813.33)}{9} = 273.15 + \frac{4066.65}{9} = 273.15 +$ $451.85 = 725.00$, so $v = 725$.
**Faster approach:** Rearrange the formula symbolically first to $v = 273.15 + \frac{5(h - 32)}{9}$, then plug in the given Fahrenheit value to avoid repeating algebraic steps.'),
  ('695f102f-4444-50b7-9239-d2d527cb4955', 3, null, '**Choice D is correct.** A quadratic has exactly one real solution when its discriminant is zero. For $25x^{2} +$ $10\sqrt{39}x + p = 0$, the discriminant is $b^{2} - 4ac = (10\sqrt{39})^{2} - 4(25)(p) = 3900 - 100p$. Setting this equal to 0 gives $3900 - 100p = 0$, so $p = 39$.
**Choice A is incorrect.** $\sqrt{39} \approx 6.245$ does not satisfy $3900 - 100p = 0$; substituting $p =\sqrt{39}$ yields a positive discriminant, so two real solutions.
**Choice B is incorrect.** $2\sqrt{39} \approx 12.49$ also does not make the discriminant zero; it leaves $3900 - 100p > 0$, giving two real solutions.
**Choice C is incorrect.** $\frac{39}{2} = 19.5$ is not equal to 39, so the discriminant is still positive and the quadratic would have two real solutions.
**Faster approach:** Use the discriminant condition $b^{2} = 4ac$ immediately; compute $(10\sqrt{39})^{2} = 100 \cdot 39$ and cancel the common factor 100 to get $39 = p$.'),
  ('bdc0b4a4-e67f-5b65-9693-278aa043914b', 2, null, '**Choice C is correct.** The factor $(0.28)^{x/12}$ gives the value after $x$ months; setting $x = 12$ (one year) yields $f(12) = 2570(0.28)$, so after one year the equipment is worth $28%$ of its previous value. That means it decreased by $100% - 28% = 72%$ during the year, so $p = 72$.
**Choice A is incorrect.** $10%$ would correspond to a yearly multiplier of $0.90$, not $0.28$; the given function shows a much larger yearly drop.
**Choice B is incorrect.** $28%$ is the remaining value fraction after one year, not the percent decreased; the percent decreased is $72%$.
**Choice D is incorrect.** $2%$ is far too small; the model clearly indicates a large annual decrease to $28%$ of the prior value.
**Faster approach:** Evaluate the exponent at $x = 12$ to get the yearly multiplier $(0.28)$, then compute $100% -$ $100 \cdot 0.28$ to find the percent decrease.'),
  ('e5ad5aee-6e25-5feb-9a62-f578303471df', 0, null, '**Choice A is correct.** Because RS = ST, S is the apex of an isosceles triangle and the altitude from S to RT also bisects RT. Let M be the midpoint of RT; then RM = MT = 48/2 = 24. In right triangle R M S, angle R is the same as in the original triangle, so $\tan R = \frac{\text{opposite}}{\text{adjacent}} = \frac{SM}{RM} = \frac{7}{24}$. Thus $SM = 7$. The area is $\frac{1}{2} \cdot \text{base} \cdot \text{height} =$ $\frac{1}{2} \cdot 48 \cdot 7 = 168$.
**Choice B is incorrect.** 288 equals $\frac{1}{2} \cdot 48 \cdot 12$, which would require a height of 12; that contradicts $\tan R =$ $7/24$ and the isosceles symmetry that gives height 7.
**Choice C is incorrect.** 84 equals $\frac{1}{2} \cdot 48 \cdot 3.5$, implying a height of 3.5, which does not match $SM = 7$ found from $\tan R$ and the bisected base.
**Choice D is incorrect.** 336 equals $\frac{1}{2} \cdot 48 \cdot 14$, implying a height of 14; that contradicts the established height $SM = 7$ from the right triangle relations.
**Faster approach:** For any isosceles triangle with equal legs at S, drop the altitude from S to the base to bisect the base; then use the given tangent in the resulting right triangle to find the height quickly and compute area as $\frac{1}{2}\cdot$base$\cdot$height.'),
  ('df81b425-c53d-578a-b535-c3543d8b5a19', 0, null, '**Choice A is correct.** For an equilateral triangle with side length $s$, the height is $\frac{\sqrt{3}}{2}s$. Set $\frac{\sqrt{3}}{2}s = 21\sqrt{3}$. Solving gives $s = \frac{2\cdot 21\sqrt{3}}{\sqrt{3}} = 42$, so the side length is 42.
**Choice B is incorrect.** $21\sqrt{3}$ is the given height, not the side; the side must be larger by a factor of $\frac{2}{\sqrt{3}}$, so it is not $21\sqrt{3}$.
**Choice C is incorrect.** $42\sqrt{3}$ is too large by a factor of $\sqrt{3}$; substituting that for $s$ would give a height of $\frac{\sqrt{3}}{2} \cdot$ $42\sqrt{3} = 63$, not $21\sqrt{3}$.
**Choice D is incorrect.** 21 is half the correct side length; using $s = 21$ would produce a height $\frac{\sqrt{3}}{2} \cdot 21 = \frac{21\sqrt{3}}{2}$, which is too small.
**Faster approach:** Memorize or recall the formula height = $\frac{\sqrt{3}}{2}s$ for equilateral triangles; solve $s = 2 \cdot$ $\text{height}/\sqrt{3}$. For quick mental work, cancel $\sqrt{3}$ immediately when it appears on both sides.'),
  ('3e56f72a-c4f5-5ec0-9c84-345649c46fc9', 2, null, '**Choice C is correct.** Factor out the gcd: $1440x^{4} - 56250 = 90(16x^{4} - 625)$. Write $16x^{4} - 625 = (4x^{2})^{2} -$ $25^{2} = (4x^{2} - 25)(4x^{2} + 25)$. Thus the polynomial factors as $90(4x^{2} + 25)(4x^{2} - 25) = 90(4x^{2} + 25)(2x -$ $5)(2x + 5)$. None of these factors equals $2x^{2} - 5$, so $2x^{2} - 5$ is NOT a factor.
